function findGoodStrings(n, s1, s2, evil) {
  const MOD = 1000000007;
  const m = evil.length;
  const fail = new Array(m).fill(0);
  let k = 0;
  for (let i = 1; i < m; i++) {
    while (k > 0 && evil[i] !== evil[k]) {
      k = fail[k - 1];
    }
    if (evil[i] === evil[k]) {
      k++;
    }
    fail[i] = k;
  }
  const step = [];
  for (let j = 0; j < m; j++) {
    step.push([]);
    for (let c = 0; c < 26; c++) {
      if (evil.charCodeAt(j) - 97 === c) {
        step[j].push(j + 1);
      } else {
        step[j].push(j === 0 ? 0 : step[fail[j - 1]][c]);
      }
    }
  }
  const empty = () => Array.from({ length: m }, () => [[0, 0], [0, 0]]);
  let dp = empty();
  dp[0][1][1] = 1;
  for (let pos = 0; pos < n; pos++) {
    const next = empty();
    const lowLetter = s1.charCodeAt(pos) - 97;
    const highLetter = s2.charCodeAt(pos) - 97;
    for (let j = 0; j < m; j++) {
      for (let low = 0; low < 2; low++) {
        for (let high = 0; high < 2; high++) {
          const count = dp[j][low][high];
          const first = low ? lowLetter : 0;
          const last = high ? highLetter : 25;
          for (let c = first; c <= last && count > 0; c++) {
            const matched = step[j][c];
            if (matched < m) {
              const nextLow = low && c === lowLetter ? 1 : 0;
              const nextHigh = high && c === highLetter ? 1 : 0;
              next[matched][nextLow][nextHigh] = (next[matched][nextLow][nextHigh] + count) % MOD;
            }
          }
        }
      }
    }
    dp = next;
  }
  let total = 0;
  for (const row of dp) {
    total = (total + row[0][0] + row[0][1] + row[1][0] + row[1][1]) % MOD;
  }
  return total;
}

brute:
function findGoodStrings(n, s1, s2, evil) {
  // Walk through every string from s1 to s2 like an odometer and test each one.
  const codes = Array.from(s1, ch => ch.charCodeAt(0) - 97);
  let count = 0;
  for (;;) {
    const word = String.fromCharCode(...codes.map(c => c + 97));
    if (!word.includes(evil)) count++;
    if (word === s2) break;
    let i = n - 1;
    while (codes[i] === 25) {
      codes[i] = 0;
      i--;
    }
    codes[i]++;
  }
  return count % 1000000007;
}

