function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const letters = rand() < 0.5 ? 3 : 26;
  const word = (length, span) => Array.from({ length }, () => String.fromCharCode(97 + int(0, span - 1))).join('');
  const n = large ? int(200, 500) : int(1, 6);
  // Small inputs keep at most 3 free letters after the shared prefix so the brute force can list the range.
  const shared = large ? (rand() < 0.5 ? int(0, n - 1) : 0) : Math.max(0, n - int(1, 3));
  const prefix = word(shared, letters);
  let a = word(n - shared, letters);
  let b = rand() < 0.2 ? a : word(n - shared, rand() < 0.5 ? letters : 26);
  if (a > b) [a, b] = [b, a];
  const s1 = prefix + a;
  const s2 = prefix + b;
  const mode = rand();
  let evil;
  if (mode < 0.3) {
    const source = rand() < 0.5 ? s1 : s2;
    const length = int(1, Math.min(source.length, large ? 50 : 4));
    const start = int(0, source.length - length);
    evil = source.slice(start, start + length);
  } else if (mode < 0.55) {
    evil = 'a'.repeat(int(1, large ? 49 : 3)) + (rand() < 0.5 ? 'b' : '');
  } else if (mode < 0.75) {
    const unit = word(int(1, 3), 3);
    evil = unit.repeat(large ? 20 : 2).slice(0, int(1, large ? 50 : 4));
  } else {
    evil = word(int(1, large ? (rand() < 0.5 ? 3 : 50) : 4), rand() < 0.5 ? 3 : 26);
  }
  return [n, s1, s2, evil];
}
